const fs = require('fs');

function solve() {
    const input = fs.readFileSync(0, 'utf-8');
    let pos = 0;

    function nextInt() {
        while (pos < input.length && input.charCodeAt(pos) <= 32) {
            pos++;
        }
        if (pos >= input.length) return null;
        let res = 0;
        let sign = 1;
        if (input.charCodeAt(pos) === 45) { // '-'
            sign = -1;
            pos++;
        }
        while (pos < input.length && input.charCodeAt(pos) > 32) {
            res = res * 10 + (input.charCodeAt(pos) - 48);
            pos++;
        }
        return res * sign;
    }

    const L = nextInt();
    if (L === null) return;
    const C = nextInt();
    const P = nextInt();

    const isBlack = Array.from({ length: L }, () => Array(C).fill(false));
    for (let i = 0; i < P; i++) {
        const r = nextInt() - 1;
        const c = nextInt() - 1;
        isBlack[r][c] = true;
    }

    const dr = [-1, 1, 0, 0];
    const dc = [0, 0, -1, 1];

    const isCandidate = Array.from({ length: L }, () => Array(C).fill(false));
    let candidateCount = 0;

    for (let r = 0; r < L; r++) {
        for (let c = 0; c < C; c++) {
            if (!isBlack[r][c]) {
                let hasBlackNeighbor = false;
                for (let d = 0; d < 4; d++) {
                    const nr = r + dr[d];
                    const nc = c + dc[d];
                    if (nr >= 0 && nr < L && nc >= 0 && nc < C && isBlack[nr][nc]) {
                        hasBlackNeighbor = true;
                        break;
                    }
                }
                if (hasBlackNeighbor) {
                    isCandidate[r][c] = true;
                    candidateCount++;
                }
            }
        }
    }

    // O grafo das células candidatas é bipartido, particionado por (r + c) % 2.
    // Usamos o algoritmo de Kuhn / DFS para encontrar o emparelhamento máximo.
    const id = Array.from({ length: L }, () => Array(C).fill(-1));
    let uCount = 0;
    let vCount = 0;

    for (let r = 0; r < L; r++) {
        for (let c = 0; c < C; c++) {
            if (isCandidate[r][c]) {
                if ((r + c) % 2 === 0) {
                    id[r][c] = uCount++;
                } else {
                    id[r][c] = vCount++;
                }
            }
        }
    }

    const adj = Array.from({ length: uCount }, () => []);
    for (let r = 0; r < L; r++) {
        for (let c = 0; c < C; c++) {
            if (isCandidate[r][c] && (r + c) % 2 === 0) {
                const u = id[r][c];
                for (let d = 0; d < 4; d++) {
                    const nr = r + dr[d];
                    const nc = c + dc[d];
                    if (nr >= 0 && nr < L && nc >= 0 && nc < C && isCandidate[nr][nc]) {
                        adj[u].push(id[nr][nc]);
                    }
                }
            }
        }
    }

    const matchV = Array(vCount).fill(-1);
    const visited = Array(uCount).fill(false);

    function dfs(u) {
        for (const v of adj[u]) {
            if (matchV[v] === -1) {
                matchV[v] = u;
                return true;
            }
        }
        for (const v of adj[u]) {
            const nextU = matchV[v];
            if (!visited[nextU]) {
                visited[nextU] = true;
                if (dfs(nextU)) {
                    matchV[v] = u;
                    return true;
                }
            }
        }
        return false;
    }

    let maxMatching = 0;
    for (let i = 0; i < uCount; i++) {
        visited.fill(false);
        visited[i] = true;
        if (dfs(i)) {
            maxMatching++;
        }
    }

    // Teorema de Kőnig: MIS = |V| - MaxMatching
    const maxWhite = candidateCount - maxMatching;
    console.log(maxWhite);
}

solve();
